def hex_to_name(hex_color):
    hex_color = hex_color.lower()
    if len(hex_color) != 6:
        return "Invalid Hex Color"
    try:
        r = int(hex_color[0:2], 16)
        g = int(hex_color[2:4], 16)
        b = int(hex_color[4:6], 16)
    except ValueError:
        return "Invalid Hex Color"
    rgb = (r, g, b)
    if rgb == (255, 0, 0):
        return "Red"
    elif rgb == (255, 165, 0):
        return "Orange"
    elif rgb == (255, 255, 0):
        return "Yellow"
    elif rgb == (0, 0, 255):
        return "Blue"
    elif rgb == (75, 0, 130):
        return "Midnight Blue"
    elif rgb == (0, 128, 0):
        return "Green"
    elif rgb == (0, 0, 0):
        return "Black"
    elif rgb == (255, 255, 255):
        return "White"
    else:
        return f"RGB({r}, {g}, {b})"
