from itertools import groupby
fruits = ["apple", "banana", "cherry", "apricot", "grape", "orange", "mango"]
fruit_types = {"apple": "pome", "banana": "berry", "cherry": "stone", "apricot": "stone", "grape": "berry", "orange": "citrus", "mango": "stone"}
sorted_fruits = sorted(fruits)
grouped_fruits = []
for fruit_type, group in groupby(sorted_fruits, key=lambda fruit: fruit_types[fruit]):
    grouped_fruits.append((fruit_type, list(group)))
if __name__ == '__main__':
    print(grouped_fruits)

def get_favorite_animals():
    favorite_animals = set()
    while True:
        user_input = input("Enter a favorite animal name (or 'done'): ")
        if user_input == 'done':
            break
        if user_input:
            favorite_animals.add(user_input.strip().lower())
    return favorite_animals
if __name__ == '__main__':
    print("Starting the process with hard-coded sample values.")
    sample_inputs = ["dog", "cat", "bird", "dog", "fish", "cat", "done", "Dog"]
    unique_animals = set()
    for animal in sample_inputs:
        if animal.lower() != 'done':
            unique_animals.add(animal.lower())
    print("Unique favorite animals found:", unique_animals)

import json
data_file = "favorite_animals.json"
def load_data():
    try:
        with open(data_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return []
    except json.JSONDecodeError:
        return []
def save_data(data):
    with open(data_file, 'w') as f:
        json.dump(data, f)
def add_animal(animals, new_name):
    animals.append(new_name)
    save_data(animals)
def view_animals(animals):
    if not animals:
        print("No favorite animals are currently tracked.")
        return
    print("--- Favorite Animals ---")
    for i, animal in enumerate(animals):
        print(f"{i+1}. {animal}")
if __name__ == '__main__':
    data = load_data()
    sample_names = ["Lion", "Tiger", "Elephant", "Bear"]
    print("--- Adding Sample Favorite Animals ---")
    for name in sample_names:
        add_animal(data, name)
        print(f"Added: {name}")
    print("\n--- Viewing All Tracked Animals ---")
    view_animals(data)

