def name_to_index_map(names):
    name_to_index = {}
    for index, name in enumerate(names):
        if name not in name_to_index:
            name_to_index[name] = index
    return name_to_index
if __name__ == '__main__':
    student_names = ["Alice", "Bob", "Alice", "Charlie", "Bob"]
    result = name_to_index_map(student_names)
    print(result)

def name_to_index(names):
    result = {}
    for index, name in enumerate(names):
        if name not in result:
            result[name] = index
    return result
if __name__ == '__main__':
    student_names = ["Alice", "Bob", "Alice", "Charlie", "Bob"]
    index_map = name_to_index(student_names)
    print(index_map)

def map_names_to_indices(names):
    name_to_index = {}
    for index, name in enumerate(names):
        if name not in name_to_index:
            name_to_index[name] = index
    return name_to_index
if __name__ == '__main__':
    student_names = ["Alice", "Bob", "Alice", "Charlie", "Bob"]
    result = map_names_to_indices(student_names)
    print(result)

def read_student_names(filename):
    student_names = []
    try:
        with open(filename, 'r') as file:
            for line in file:
                student_names.append(line.strip())
    except FileNotFoundError:
        print(f"Error: The file {filename} was not found.")
        return None
    except IOError as e:
        print(f"Error reading file {filename}: {e}")
        return None
    return student_names
if __name__ == '__main__':
    file_name = 'students.txt'
    try:
        with open(file_name, 'w') as f:
            f.write("Alice\n")
            f.write("Bob\n")
            f.write("Charlie\n")
            f.write("  Diana \n")
        names = read_student_names(file_name)
        if names is not None:
            print("Student Names Read:")
            for name in names:
                print(name)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

