    dict_d = {'x': 'hello', 'z': 'test'}
    result2 = match_keys_to_values(dict_c, dict_d)
    print(result2)
    dict_e = {'k1': 10, 'k2': 20}
    dict_f = {'k1': 10, 'k3': 30}
    result3 = match_keys_to_values(dict_e, dict_f)
    print(result3)

