def find_matching_pairs(d1, d2):
    keys1 = set(d1.keys())
    keys2 = set(d2.keys())
    matching_keys = keys1.intersection(keys2)
    matching_pairs = []
    for key in matching_keys:
        if key in d1 and key in d2:
            matching_pairs.append((key, d1[key], d2[key]))
    return matching_pairs
