class KeyMatcher:
    def match(self, dict1: dict, dict2: dict) -> bool:
        if len(dict1) != len(dict2):
            return False
        for key, value1 in dict1.items():
            if key not in dict2:
                return False
            if dict2[key] != value1:
                return False
        return True
