class KeyMatcher:
    def match(self, dict1, dict2):
        if not dict1 or not dict2:
            return {}
        result = {}
        for key, value1 in dict1.items():
            if key in dict2:
                value2 = dict2[key]
                if value1 == value2:
                    result[key] = value1
        return result
